BEGIN TRANSACTION;
DROP TABLE narrative_usage;
CREATE TABLE narrative_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, call_site TEXT NOT NULL, model TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cache_read_tokens INTEGER NOT NULL DEFAULT 0, cache_creation_tokens INTEGER NOT NULL DEFAULT 0, duration_ms INTEGER NOT NULL DEFAULT 0, success INTEGER NOT NULL DEFAULT 1);
COMMIT;
